/**
 * @title No access, with a request form
 * @description Explains why the page is hidden and who can help, then lets the person ask for access with a note. Confirms the request without leaving the page.
 * @route /reports
 */
import { TopBar } from "@/components/top-bar";
import { RequestAccess } from "@/components/request-access";

export default function Page() {
  return (
    <div className="flex min-h-svh flex-col bg-canvas">
      <TopBar current="Overview" />
      <main id="main" className="mx-auto flex w-full max-w-xl flex-1 flex-col justify-center gap-6 px-4 py-12">
        <RequestAccess />
      </main>
    </div>
  );
}

"use client";
import { Gauge } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";

const links = ["Overview", "Customers", "Products", "Settings"];

/** A header-only app layout: logo, top navigation and the account menu. */
export function TopBar({ current = "Overview" }: { current?: string }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] border-b border-line-default bg-surface">
      <div className="mx-auto flex h-14 max-w-7xl items-center gap-6 px-4 md:px-6">
        <a href="#" className="flex items-center gap-2 rounded-sm text-label-large focus-visible:focus-ring">
          <span className="grid size-7 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={Gauge} size={16} /></span>
          Acme
        </a>
        <nav aria-label="Main" className="max-md:hidden">
          <ul className="flex items-center gap-1">
            {links.map((l) => (
              <li key={l}>
                <a href="#" aria-current={l === current ? "page" : undefined}
                  className="flex h-8 items-center rounded-control px-3 text-label-medium text-fg-secondary hover:bg-neutral-hover hover:text-fg-primary focus-visible:focus-ring aria-[current=page]:text-fg-primary">
                  {l}
                </a>
              </li>
            ))}
          </ul>
        </nav>
        <div className="ms-auto">
          <Menu
            label="Account menu for Jane Cooper"
            items={[{ label: "Profile", icon: "user" }, { label: "Settings", icon: "settings" }, { label: "Sign out", icon: "sign-out", separatorBefore: true }]}
            trigger={({ ref, ...p }) => (
              <button ref={ref} type="button" {...p} aria-label="Account menu for Jane Cooper" className="rounded-full focus-visible:focus-ring">
                <Avatar name="Jane Cooper" decorative />
              </button>
            )}
          />
        </div>
      </div>
    </header>
  );
}

"use client";
import { useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Avatar } from "@/components/ui/display";
import { Alert } from "@/components/ui/feedback";
import { Textarea } from "@/components/ui/form";
import { Icon } from "@/components/ui/icon";

export function RequestAccess() {
  const [sent, setSent] = useState(false);
  const status = useRef<HTMLDivElement>(null);
  return (
    <section aria-labelledby="na-title" className="flex flex-col gap-6 rounded-container border border-line-default bg-surface p-6 sm:p-8">
      <div className="flex flex-col items-center gap-3 text-center">
        <span className="grid size-12 place-items-center rounded-full bg-surface-subtle text-icon-primary"><Icon name="lock" /></span>
        <h1 id="na-title" className="text-heading-h2">You don't have access to Reports</h1>
        <p className="text-body-medium text-fg-secondary">Reports are limited to admins of the Acme Inc workspace. An admin can give you access.</p>
      </div>
      <div className="flex items-center gap-3 rounded-container bg-surface-subtle p-3">
        <Avatar name="Wade Warren" />
        <p className="flex flex-col text-body-small"><span className="text-label-medium">Wade Warren</span><span className="text-fg-secondary">Workspace admin · usually replies within a day</span></p>
      </div>
      <div ref={status} tabIndex={-1} className="outline-none">
        {sent ? (
          <Alert tone="success" title="Request sent" live>We'll email you when Wade answers. You can keep working in the meantime.</Alert>
        ) : (
          <form className="flex flex-col gap-4" onSubmit={(e) => { e.preventDefault(); setSent(true); requestAnimationFrame(() => status.current?.focus()); }}>
            <Textarea label="Note to the admin (optional)" placeholder="Why do you need access?" maxLength={240} />
            <div className="flex flex-wrap gap-2"><Button type="submit" leadingIcon="send">Request access</Button><Button type="button" variant="secondary">Go to dashboard</Button></div>
          </form>
        )}
      </div>
    </section>
  );
}
